const cash=(v)=>"KES "+Number(v||0).toLocaleString("en-KE");
const date=(v)=>v?new Intl.DateTimeFormat("en-KE",{day:"numeric",month:"short"}).format(new Date(v)):"-";
const join=(...v)=>v.filter(Boolean).join(" ");

function Btn({children,kind="primary",className="",...props}){return <button className={join("btn","btn-"+kind,className)} {...props}>{children}</button>}
function Brand({onClick}){return <button className="brand" onClick={onClick}><span className="brand-leaf"><Sprout size={21}/></span><span>shamba<span>link</span><small>Grow well. Sell fairly.</small></span></button>}
function Notice({error,children,close}){return children?<div className={"notice "+(error?"error":"")} role="status"><b>{error?"!":<Check size={14}/>}</b><span>{children}</span>{close&&<button aria-label="Dismiss" onClick={close}><X size={15}/></button>}</div>:null}
function Dialog({title,close,children}){useEffect(()=>{const key=e=>e.key==="Escape"&&close();window.addEventListener("keydown",key);document.body.classList.add("lock-scroll");return()=>{window.removeEventListener("keydown",key);document.body.classList.remove("lock-scroll")}},[close]);return <div className="backdrop" onMouseDown={e=>e.target===e.currentTarget&&close()}><section className="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header><div><small className="eyebrow">SHAMBALINK</small><h2 id="dialog-title">{title}</h2></div><button className="icon-btn" onClick={close} aria-label="Close"><X/></button></header>{children}</section></div>}
function Auth({mode,change,close,send,error,busy}){const[role,setRole]=useState("farmer");const[v,setV]=useState({full_name:"",phone:"",email:"",password:""});const edit=e=>setV({...v,[e.target.name]:e.target.value});return <Dialog title={mode==="login"?"Welcome back":"Join the growing community"} close={close}><div className="toggle"><button className={mode==="login"?"sel":""} onClick={()=>change("login")}>Sign in</button><button className={mode==="signup"?"sel":""} onClick={()=>change("signup")}>Create account</button></div>{mode==="signup"&&<div className="roles"><button className={role==="farmer"?"sel":""} onClick={()=>setRole("farmer")}><Sprout size={16}/> Farmer</button><button className={role==="buyer"?"sel":""} onClick={()=>setRole("buyer")}><ShoppingBasket size={16}/> Buyer</button></div>}<form className="form" onSubmit={e=>{e.preventDefault();send(v,role)}}>{mode==="signup"&&<><label>Full name<input name="full_name" value={v.full_name} onChange={edit} autoComplete="name" required minLength="2" placeholder="e.g. Wanjiku Kamau"/></label><label>Phone number<input name="phone" value={v.phone} onChange={edit} autoComplete="tel" required minLength="10" placeholder="+254 712 345 678"/></label></>}<label>Email address<input name="email" value={v.email} onChange={edit} autoComplete="email" type="email" required placeholder="you@example.com"/></label><label>Password<input name="password" value={v.password} onChange={edit} autoComplete={mode==="login"?"current-password":"new-password"} type="password" required minLength={mode==="login"?1:8}/></label><Notice error>{error}</Notice><Btn type="submit" disabled={busy}>{busy?"Please wait...":mode==="login"?"Sign in securely":"Create my account"}<ArrowRight size={16}/></Btn><small className="secure"><ShieldCheck size={14}/> Your account details are protected.</small></form></Dialog>}
function Art({i=0,category}){return <div className={"product-art art-"+(i%4)} aria-hidden="true"><span className="art-sun"/><span className="art-hill one"/><span className="art-hill two"/><span className="art-produce"><i/><i/><i/></span><small>{category||"Fresh harvest"}</small></div>}
function Product({p,i,user,buy,auth}){return <article className="product">{p.product_images?.[0]?<img className="product-photo" src={p.product_images[0]} alt={p.product_name} loading="lazy" onError={e=>{e.currentTarget.hidden=true}}/>:<Art i={i} category={p.category}/>}<div className="product-body"><div className="product-label"><span>{p.category}</span><span className="fresh"><i/> In season</span></div><h3>{p.product_name}</h3><p className="location"><MapPin size={14}/>{p.sub_county}, {p.county}</p><div className="price"><div><b>{cash(p.price_per_unit_kes)}</b><small>/ {p.unit} | {p.quantity_available} available</small></div><button className="arrow-circle" aria-label={"Order "+p.product_name} onClick={()=>user?.role==="BUYER"?buy(p):auth()}><ArrowRight size={17}/></button></div></div></article>}
function Empty({icon:Icon=Sprout,title,text,action,click}){return <div className="empty"><span><Icon size={22}/></span><h3>{title}</h3><p>{text}</p>{action&&<Btn kind="outline" onClick={click}>{action}<ArrowRight size={15}/></Btn>}</div>}
function Order({o,role,pay,deliver,confirm,dispute,busy}){const status=(o.order_status||"PENDING").replaceAll("_"," ");return <article className="order-row"><span className="order-mark"><Package size={17}/></span><div className="order-main"><b>{o.product_name||"Order "+o.id?.slice(-6)}</b><small>{date(o.created_at)} | {o.quantity} {o.unit}</small></div><span className={"pill "+status.toLowerCase().replaceAll(" ","-")}>{status}</span><b className="order-total">{cash(o.total_amount_kes)}</b><div className="order-actions">{role==="BUYER"&&o.order_status==="AWAITING_PAYMENT"&&<Btn onClick={pay} disabled={busy}><CreditCard size={14}/> Pay</Btn>}{role==="FARMER"&&["PAID","PROCESSING","READY_FOR_DELIVERY"].includes(o.order_status)&&<Btn kind="outline" onClick={deliver} disabled={busy}><Truck size={14}/> Delivery</Btn>}{role==="BUYER"&&o.order_status==="DELIVERED"&&<Btn onClick={confirm}><Check size={14}/> Confirm</Btn>}{role==="BUYER"&&["PAID","PROCESSING","IN_TRANSIT","DELIVERED"].includes(o.order_status)&&<button className="link danger" onClick={dispute}>Dispute</button>}</div></article>}

